  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
  await answerFrame(ws, session, sessionStore, validation);
}

async function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  validation: ValidationResult
): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') {
    handlePing(ws, message.timestamp);
    return;
  }
  if (message.type === 'list_sessions') {
    await handleListSessions(ws, session, sessionStore, message);
  }
}

function handlePing(ws: WebSocket, timestamp: number): void {
  ws.send(JSON.stringify({type: 'pong', timestamp}));
}

async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  if (!sessionStore?.listFor) {
    sendJson(ws, {type: 'session_list', sessions: []});
    return;
  }

  try {
    const options: SessionListOptions = {limit: message.limit, before: message.before};
    const summaries = await sessionStore.listFor(session.userId, options);
    const sessions: SessionSummaryFrame[] = summaries.map(s => ({
      sessionId: s.sessionId,
      createdAt: s.createdAt instanceof Date ? s.createdAt.toISOString() : new Date(s.createdAt).toISOString(),
      updatedAt: s.updatedAt instanceof Date ? s.updatedAt.toISOString() : new Date(s.updatedAt).toISOString(),
      entryCount: s.entryCount,
    }));
    sendJson(ws, {type: 'session_list', sessions});
  } catch (error) {
    const errMessage = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'failed to list sessions', {userId: session.userId, error: errMessage});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

